def unverified_items() -> list[str]:
    """Items whose shipped default is an unmeasured placeholder.

    The ECU raises an informational DTC when an unverified item is used
    outside bench/dyno mode, and the GUI badges them in the calibration
    browser.  See docs/CALIBRATION_SPEC.md 1.
    """
    return [d.name for d in DESCRIPTORS if d.default_source == "UNVERIFIED"]

